export default async function start({ acknowledge }, ctx) {
  const s = await ctx.state.get("mysql-clean");
  if (s?.pending) {
    if (acknowledge !== s.runId)
      throw Error("Inspect both databases and Telegram for cleanup " + s.runId);
    await ctx.state.set("mysql-clean", null);
  }
  const runId = String(Date.now());
  await ctx.state.set("mysql-clean", { runId, pending: false, unresolved: [] });
  return { runId };
}

