export default async function results({ runId, body }, ctx) {
  if (!body || typeof body.first !== "boolean" || typeof body.second !== "boolean")
    throw Error("Relay did not confirm both database outcomes");
  const s = await ctx.state.get("mysql-clean");
  if (!s || s.runId !== runId) throw Error("Cleanup state mismatch");
  if (!body.first) s.unresolved.push("first database");
  if (!body.second) s.unresolved.push("second database");
  await ctx.state.set("mysql-clean", s);
  return { first: body.first, second: body.second };
}

