export default async function finish({ runId }, ctx) {
  const s = await ctx.state.get("mysql-clean");
  if (!s || s.runId !== runId) throw Error("Cleanup state mismatch");
  if (s.unresolved.length) {
    s.pending = true;
    await ctx.state.set("mysql-clean", s);
    throw Error("Inspect cleanup " + runId + ": " + s.unresolved.join(", "));
  }
  await ctx.state.set("mysql-clean", null);
  return { ok: true };
}
